const events = []
let release
const held = new Promise(resolve => { release = resolve })
const analytics = createServer(async (req, res) => {
  const chunks = []
  for await (const chunk of req) chunks.push(chunk)
  events.push({ method: req.method, body: JSON.parse(Buffer.concat(chunks).toString()), authorization: req.headers.authorization })
  await held
  res.writeHead(204).end()
})
analytics.listen(0, '127.0.0.1')
await once(analytics, 'listening')
const analyticsPort = analytics.address().port
const appPort = await freePort()
const app = spawn(process.execPath, ['node_modules/next/dist/bin/next', 'start', '-p', String(appPort)], {
  env: { ...process.env, ANALYTICS_ENDPOINT: `http://127.0.0.1:${analyticsPort}/events`, ANALYTICS_API_KEY: 'test-key' },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', data => { output += data.toString() })
app.stderr.on('data', data => { output += data.toString() })
