  const deadline = Date.now() + 10000
  while (!output.includes('Ready in') && Date.now() < deadline && app.exitCode === null) {
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  assert.match(output, /Ready in/, `App failed to start: ${output}`)
